public with sharing class ContactTriggerHandler {

    // Accounts queried in the before context, reused in the after context
    // so the whole trigger uses at most 1 SOQL and 1 DML statement.
    private static Map<Id, Account> accountsById;

    /**
     * Single bulkified query for all accounts referenced by the contacts.
     * Runs once per trigger invocation (before insert/update).
     */
    public void populateAccountData(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            accountsById = new Map<Id, Account>();
            return;
        }
        accountsById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource, Phone
             FROM Account
             WHERE Id IN :accountIds]
        );
    }

    /**
     * Original before-context behaviour: default MailingCountry from the
     * account's BillingCountry and, on insert only, LeadSource from the
     * account's AccountSource, when blank on the contact.
     */
    public void setContactFieldsFromAccount(List<Contact> contacts, Boolean isInsert) {
        for (Contact c : contacts) {
            if (c.AccountId != null && accountsById.containsKey(c.AccountId)) {
                Account a = accountsById.get(c.AccountId);
                if (String.isBlank(c.MailingCountry)) {
                    c.MailingCountry = a.BillingCountry;
                }
                if (isInsert && String.isBlank(c.LeadSource)) {
                    c.LeadSource = a.AccountSource;
                }
            }
        }
    }

    /**
     * Original after-insert behaviour: for each account with no phone, the
     * first contact (in trigger order) that has a phone sets the account's
     * phone. Accounts are updated in a single DML statement.
     */
    public void setDefaultAccountPhone(List<Contact> contacts) {
        if (accountsById == null) {
            return;
        }
        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact c : contacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null || !String.isBlank(a.Phone)) {
                continue;
            }
            // First contact in trigger order wins; skip subsequent ones.
            if (accountsToUpdate.containsKey(c.AccountId)) {
                continue;
            }
            Account updated = new Account(
                Id = a.Id,
                Phone = c.Phone
            );
            accountsToUpdate.put(c.AccountId, updated);
        }
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }
}
