import { LightningElement, api } from 'lwc';

const NAVIGATION_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    @api label = '';
    @api options = [];

    _value = '';
    // null means "the active option should follow the current value
    // (or the first option when nothing is selected)". A number means
    // the user has explicitly moved the active option.
    _activeIndex = null;
    _uid = 'status-listbox-' + Math.random().toString(36).slice(2, 10);

    @api
    get value() {
        return this._value;
    }
    set value(newValue) {
        this._value = newValue ?? '';
        // The active option moves to the new selection.
        this._activeIndex = null;
    }

    get displayOptions() {
        return this.options.map((option, index) => ({
            ...option,
            index,
            id: this.optionId(index),
            isSelected: option.value === this._value,
            isActive: index === this.activeIndex,
            classes: option.value === this._value ? 'slds-is-selected' : ''
        }));
    }

    get activeIndex() {
        if (this._activeIndex !== null) {
            return this._activeIndex;
        }
        const selectedIndex = this.options.findIndex(
            (option) => option.value === this._value
        );
        return selectedIndex >= 0 ? selectedIndex : 0;
    }

    get activeId() {
        return this.optionId(this.activeIndex);
    }

    optionId(index) {
        return `${this._uid}-option-${index}`;
    }

    handleKeydown(event) {
        if (!NAVIGATION_KEYS.includes(event.key)) {
            // e.g. Tab: keep default behaviour.
            return;
        }
        event.preventDefault();

        const length = this.options.length;
        if (length === 0) {
            return;
        }

        let index = this.activeIndex;
        switch (event.key) {
            case 'ArrowDown':
                index = Math.min(index + 1, length - 1);
                break;
            case 'ArrowUp':
                index = Math.max(index - 1, 0);
                break;
            case 'Home':
                index = 0;
                break;
            case 'End':
                index = length - 1;
                break;
            case 'Enter':
            case ' ':
                this.select(index);
                return;
            default:
                return;
        }
        // Moving the active option does not change the selection.
        this._activeIndex = index;
    }

    handleClick(event) {
        const optionEl = event.target.closest('li[data-index]');
        if (!optionEl) {
            return;
        }
        const index = Number(optionEl.dataset.index);
        if (Number.isNaN(index) || index < 0 || index >= this.options.length) {
            return;
        }
        this.select(index);
    }

    select(index) {
        const option = this.options[index];
        if (!option) {
            return;
        }
