/**
 * FamilyService
 * Imports NPSP parent/child relationship links.
 *
 * Strategy: for each (child, parent) pair we insert exactly one
 * npe4__Relationship__c from the PARENT to the CHILD with Type = 'Parent'
 * and Status = 'Current'. NPSP's Relationship trigger (List Setting
 * reciprocal method) then automatically creates the single reciprocal
 * record from the CHILD to the PARENT, resolving the type via the
 * active 'Parent' row of npe4__Relationship_Lookup__c
 * (Male: Son, Female: Daughter, Neutral: Child).
 *
 * Limits (per call, our own usage):
 *   - 1 SOQL query  (Contacts with their relationships, parent-subquery)
 *   - 1 DML statement (insert of the parent-side relationships)
 */
public inherited sharing class FamilyService {

    /**
     * @param parentIdByChildId map of child Contact Id -> parent Contact Id
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Null or empty input: do nothing.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect every contact involved so a single SOQL query can
        // fetch all existing relationships for all of them.
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            if (childId != null) {
                contactIds.add(childId);
            }
            Id parentId = parentIdByChildId.get(childId);
            if (parentId != null) {
                contactIds.add(parentId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // One query: every contact plus all relationship records in
        // which they appear (in either direction).
        Map<Id, Set<Id>> relatedContactIdsByContact = new Map<Id, Set<Id>>();
        for (Contact c : [
            SELECT Id,
                   (
                       SELECT npe4__Contact__c, npe4__RelatedContact__c
                       FROM npe4__Relationships__r
                   )
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            Set<Id> related = new Set<Id>();
            for (npe4__Relationship__c rel : c.npe4__Relationships__r) {
                if (rel.npe4__Contact__c != null) {
                    related.add(rel.npe4__Contact__c);
                }
                if (rel.npe4__RelatedContact__c != null) {
                    related.add(rel.npe4__RelatedContact__c);
                }
            }
            relatedContactIdsByContact.put(c.Id, related);
        }

        List<npe4__Relationship__c> newRelationships = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            // Skip malformed pairs.
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            Set<Id> childRelated = relatedContactIdsByContact.get(childId);
            Set<Id> parentRelated = relatedContactIdsByContact.get(parentId);

            // Contacts not returned by the query do not exist; skip.
            if (childRelated == null || parentRelated == null) {
                continue;
            }

            // Skip if ANY relationship already exists between the two
            // contacts, in either direction. Also update the in-memory
            // sets so duplicate pairs within this same call are skipped.
            if (childRelated.contains(parentId) || parentRelated.contains(childId)) {
                continue;
            }

            newRelationships.add(new npe4__Relationship__c(
                npe4__Contact__c = parentId,
                npe4__RelatedContact__c = childId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current',
                npe4__Description__c = 'Family import'
            ));

            childRelated.add(parentId);
            parentRelated.add(childId);
        }

        // Single DML statement. NPSP's trigger creates the reciprocal
        // child-side record (Son / Daughter / Child per the lookup).
        if (!newRelationships.isEmpty()) {
            insert newRelationships;
        }
    }
}
