public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    private static final Set<String> QUALIFYING_TYPES = new Set<String>{
        'Customer - Direct', 'Customer - Channel'
    };
    private static final String TASK_SUBJECT = 'Onboard new customer';
    private static final Integer DAYS_UNTIL_DUE = 7;

    public void afterInsert(List<SObject> triggerNew) {
        List<Account> accounts = (List<Account>) triggerNew;
        List<Task> tasks = new List<Task>();
        Date dueDate = Date.today().addDays(DAYS_UNTIL_DUE);

        for (Account account : accounts) {
            if (account.Type != null && QUALIFYING_TYPES.contains(account.Type)) {
                tasks.add(new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = account.Id,
                    OwnerId = account.OwnerId,
                    ActivityDate = dueDate,
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
